package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="warehouses") public class Warehouse { @Id private String id; @Indexed(unique=true) private String code; private String name; private String location; private boolean active=true; private LocalDateTime createdAt=LocalDateTime.now(); public Warehouse(){} public String getId(){return id;} public void setId(String v){id=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
